net.ipv4.tcp_tw_reuse = 1
fs.file-max = 2097152`}],jL=({isOpen:e,onClose:t,initialFilePath:n="/etc/nginx/nginx.conf",initialContent:r="",onSaveToRemote:s})=>{const[a,o]=A.useState(n),[l,c]=A.useState(r||Lh[0].content),[d,m]=A.useState(r||Lh[0].content),[u,x]=A.useState("editor"),[g,y]=A.useState(!1),[v,b]=A.useState(!1);if(!e)return null;const h=w=>{o(w.path),c(w.content),m(w.content)},f=()=>{s&&s(a,d),y(!0),setTimeout(()=>y(!1),2500)},p=()=>{navigator.clipboard.writeText(d),b(!0),setTimeout(()=>b(!1),2e3)},_=l.split(`
